cat > internal/analysis/fanout/fanout.go <<'SETUP_EOF'
// Package fanout counts, for each package in a []core.SymbolNode, how many
// distinct OTHER packages it calls into (its fan-out).
package fanout

import (
	"sort"
	"strings"

	"github.com/geoffmilleraz/fathom/internal/core"
)

// Entry is one package's fan-out count.
type Entry struct {
	Package string
	FanOut  int
}

// Compute returns each package's fan-out count, ordered by Package name.
func Compute(nodes []core.SymbolNode) []Entry {
	targets := make(map[string]map[string]bool)
	for _, n := range nodes {
		if n.Package == "" {
			continue
		}
		if _, ok := targets[n.Package]; !ok {
			targets[n.Package] = make(map[string]bool)
		}
		for _, callee := range n.Calls {
			toPkg := calleePackage(callee)
			if toPkg == "" || toPkg == n.Package {
				continue
			}
			targets[n.Package][toPkg] = true
		}
	}

	entries := make([]Entry, 0, len(targets))
	for pkg, set := range targets {
		entries = append(entries, Entry{Package: pkg, FanOut: len(set)})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Package < entries[j].Package })
	return entries
}

// calleePackage extracts the package segment from a Calls entry
// ("svc::pkg.Name" or "pkg.Name" -> "pkg"; "Name" -> "").
func calleePackage(key string) string {
	if idx := strings.Index(key, "::"); idx >= 0 {
		key = key[idx+2:]
	}
	if dot := strings.LastIndex(key, "."); dot > 0 {
		return key[:dot]
	}
	return ""
}

SETUP_EOF

cat > internal/analysis/fanout/fanout_test.go <<'SETUP_EOF'
package fanout_test

import (
	"reflect"
	"sort"
	"testing"

	"github.com/geoffmilleraz/fathom/internal/analysis/fanout"
	"github.com/geoffmilleraz/fathom/internal/core"
)

// symbols spans eight packages so an unsorted result is overwhelmingly
// unlikely to look accidentally sorted.
var symbols = []core.SymbolNode{
	{Package: "delta", Name: "F", Kind: core.KindGoFunc, Calls: []string{"alpha.G", "zeta.H"}},
	{Package: "alpha", Name: "G", Kind: core.KindGoFunc, Calls: []string{"kappa.I"}},
	{Package: "zeta", Name: "H", Kind: core.KindGoFunc, Calls: []string{"mu.J"}},
	{Package: "kappa", Name: "I", Kind: core.KindGoFunc},
	{Package: "mu", Name: "J", Kind: core.KindGoFunc, Calls: []string{"theta.K"}},
	{Package: "theta", Name: "K", Kind: core.KindGoFunc, Calls: []string{"beta.L"}},
	{Package: "beta", Name: "L", Kind: core.KindGoFunc, Calls: []string{"omega.M"}},
	{Package: "omega", Name: "M", Kind: core.KindGoFunc},
}

func TestCompute_Counts(t *testing.T) {
	got := fanout.Compute(symbols)
	want := map[string]int{
		"alpha": 1, "beta": 1, "delta": 2, "kappa": 0,
		"mu": 1, "omega": 0, "theta": 1, "zeta": 1,
	}
	if len(got) != len(want) {
		t.Fatalf("Compute returned %d entries, want %d: %+v", len(got), len(want), got)
	}
	for _, e := range got {
		if w, ok := want[e.Package]; !ok || w != e.FanOut {
			t.Errorf("Compute: %s fan-out = %d, want %d", e.Package, e.FanOut, want[e.Package])
		}
	}
}

// TestFanoutDeterministic is this package's own determinism gate
// (internal/CLAUDE.md's contract: "sort every output slice; map iteration
// order must never reach a result").
func TestFanoutDeterministic(t *testing.T) {
	e1 := fanout.Compute(symbols)
	e2 := fanout.Compute(symbols)
	if !reflect.DeepEqual(e1, e2) {
		t.Fatalf("non-deterministic Compute: %+v vs %+v", e1, e2)
	}
	if !sort.SliceIsSorted(e1, func(i, j int) bool { return e1[i].Package < e1[j].Package }) {
		t.Fatalf("Compute result is not sorted by package: %+v", e1)
	}
}

SETUP_EOF

