cat > internal/store/search.go <<'SETUP_EOF'
package store

import "strings"

// Search does a substring scan over candidates for query, returning the
// matches in their original order. When SearchAccelerated reports true a
// caller may also consult a faster index directly; the scan below is the
// correctness fallback every build can run.
func Search(candidates []string, query string) []string {
	_ = SearchAccelerated()
	if query == "" {
		return nil
	}
	var out []string
	for _, c := range candidates {
		if strings.Contains(c, query) {
			out = append(out, c)
		}
	}
	return out
}

SETUP_EOF

cat > internal/store/search_test.go <<'SETUP_EOF'
package store_test

import (
	"reflect"
	"testing"

	"github.com/geoffmilleraz/fathom/internal/store"
)

func TestSearch(t *testing.T) {
	candidates := []string{"alpha", "beta", "alphabet", "gamma"}
	got := store.Search(candidates, "alpha")
	want := []string{"alpha", "alphabet"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Search(%q) = %v, want %v", "alpha", got, want)
	}
	if got := store.Search(candidates, ""); got != nil {
		t.Fatalf("Search(\"\") = %v, want nil", got)
	}
}

func TestSearchAccelerated_DefaultsFalse(t *testing.T) {
	if store.SearchAccelerated() {
		t.Fatal("SearchAccelerated() = true in a build with no accelerator linked")
	}
}

SETUP_EOF

